from typing import TypeVar, Callable, Optional

T = TypeVar('T')

def binary_search(arr: list[T], target: T, key: Callable[[T], any] = None) -> int:
    """EGRR_PATTERN: Binary search with edge case handling.

    Returns index of target if found, -1 otherwise.
    Handles empty arrays, single elements, and custom key functions.
    """
    if not arr:
        return -1

    key = key or (lambda x: x)
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2  # Avoid overflow
        mid_val = key(arr[mid])
        target_val = key(target) if callable(key) else target

        if mid_val == target_val:
            return mid
        elif mid_val < target_val:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def binary_search_leftmost(arr: list[T], target: T) -> int:
    """EGRR_PATTERN: Find leftmost occurrence of target."""
    if not arr:
        return -1

    left, right = 0, len(arr)

    while left < right:
        mid = left + (right - left) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid

    if left < len(arr) and arr[left] == target:
        return left
    return -1

def binary_search_rightmost(arr: list[T], target: T) -> int:
    """EGRR_PATTERN: Find rightmost occurrence of target."""
    if not arr:
        return -1

    left, right = 0, len(arr)

    while left < right:
        mid = left + (right - left) // 2
        if arr[mid] <= target:
            left = mid + 1
        else:
            right = mid

    if left > 0 and arr[left - 1] == target:
        return left - 1
    return -1
